"""Offline final rehearsal. Real runner/kit, fake tables, fake time, no credentials.

Run explicitly: PYTHONPATH=. python -m pytest audits/test_final_rehearsal.py -q
Failed assertions are unmet operational invariants, not expected-failure markers.
"""

import copy
import json
import threading
from concurrent.futures import Future
from types import SimpleNamespace

import pytest
from arena_kit.client import ArenaError
from arena_kit.play import RemoteTable
from arena_kit.sim import load_cases

from buyer import agent, policy, runner


class Clock:
    def __init__(self):
        self.now = 1000.0

    def time(self):
        return self.now

    monotonic = time

    def sleep(self, seconds):
        self.now += seconds


class ScriptedNegotiator:
    """Only policy is substituted; production scheduling, recovery and close are exercised."""

    delay = 0
    setup_delay = 0
    clock = None

    def __init__(self, case, pkg=None, complete=None):
        self.sides, self.notes = {}, []

    def setup(self, sid, events):
        self.clock.sleep(self.setup_delay)
        self.sides[sid] = SimpleNamespace(quote=len(self.sides) + 1, state="open")

    def move(self, sid, threads):
        self.clock.sleep(self.delay)
        self.sides[sid].state = "done"
        return {"message": {"body": "Please confirm the offer."}}

    def commit(self, sid):
        pass

    def rollback(self, sid):
        self.sides[sid].state = "ended"

    def close(self, threads):
        return {"supplier_id": next(iter(threads)), "message": {"action": {"type": "walk_away"}}}

    def fallback_close(self, threads):
        return next(iter(threads)), {"action": {"type": "walk_away"}}


class Table:
    session_id = "offline-session"
    done = None

    def __init__(self, clock, suppliers=3, reply_delay=0, terminal=False, close_errors=0):
        self.clock = clock
        self.reply_delay, self.terminal, self.close_errors = reply_delay, terminal, close_errors
        self.threads = {f"supplier:{i}": [{"from": "supplier", "status": "open"}] for i in range(suppliers)}
        self.reply_at = dict.fromkeys(self.threads, clock.now)
        self.sends, self.close_calls, self.inflight, self.max_inflight = [], 0, 0, 0
        self.final_result = {"deal": False, "end_reason": "no_deal"}

    def open(self, case_id):
        return {"round_limit": 10}, copy.deepcopy(self.threads)

    def send(self, sid, message):
        age = self.clock.now - self.reply_at[sid]
        self.sends.append((sid, age))
        if age > 60:
            raise ArenaError(409, "late buyer message")
        self.inflight += 1
        self.max_inflight = max(self.max_inflight, self.inflight)
        self.clock.sleep(self.reply_delay)
        self.inflight -= 1
        self.reply_at[sid] = self.clock.now
        if self.terminal:
            return {"from": "supplier", "status": "walked_away", "result": self.final_result}
        return {"from": "supplier", "status": "open"}

    def missed(self, sid, error):
        return {"from": "supplier", "status": "walked_away"}

    def close(self, sid, message):
        self.close_calls += 1
        if self.close_calls <= self.close_errors:
            raise ArenaError(409, "session already ended")
        return self.final_result

    def result(self):
        return self.final_result


@pytest.fixture
def clock(monkeypatch):
    clock = Clock()
    monkeypatch.setattr(runner, "time", clock)
    monkeypatch.setattr(policy, "time", clock)
    monkeypatch.setattr(runner, "save", lambda *args: None)
    return clock


@pytest.fixture
def scheduler(monkeypatch, clock):
    monkeypatch.setattr(ScriptedNegotiator, "clock", clock)
    monkeypatch.setattr(ScriptedNegotiator, "delay", 0)
    monkeypatch.setattr(ScriptedNegotiator, "setup_delay", 0)
    monkeypatch.setattr(runner, "Negotiator", ScriptedNegotiator)
    return ScriptedNegotiator


def test_serial_sends_within_a_session(clock, scheduler):
    table = Table(clock, reply_delay=2)
    runner.play_case(table, "case:offline")
    assert table.max_inflight == 1
    assert len(table.sends) == 3
    assert max(age for _, age in table.sends) <= 60


def test_slow_writer_plus_network_meets_each_thread_deadline(clock, scheduler):
    scheduler.delay = 20  # configured model timeout; supplier response is additional
    table = Table(clock, reply_delay=5)
    runner.play_case(table, "case:offline")
    assert max(age for _, age in table.sends) <= 60, table.sends


def test_setup_time_counts_against_opening_deadlines(clock, scheduler):
    scheduler.setup_delay = 25
    table = Table(clock)
    runner.play_case(table, "case:offline")
    assert max(age for _, age in table.sends) <= 60, table.sends


def test_terminal_send_returns_result_without_another_close(clock, scheduler):
    table = Table(clock, suppliers=1, terminal=True)
    assert runner.play_case(table, "case:offline") == table.final_result
    assert table.close_calls == 0, "A successful send already returned the terminal result"


def test_already_ended_close_recovers_server_result(clock, scheduler):
    table = Table(clock, suppliers=1, close_errors=2)
    assert runner.play_case(table, "case:offline") == table.final_result


def test_retry_one_rejected_close(clock, scheduler):
    table = Table(clock, suppliers=1, close_errors=1)
    assert runner.play_case(table, "case:offline") == table.final_result
    assert table.close_calls == 2


def test_near_wave_cap_closes_without_new_round(clock, scheduler):
    table = Table(clock, suppliers=1)
    runner.play_case(table, "case:offline", deadline=clock.now + 89)
    assert table.sends == []
    assert table.close_calls == 1


def test_slow_round_keeps_time_to_close(clock, scheduler):
    scheduler.delay = 20
    table = Table(clock, suppliers=1, reply_delay=100)
    cap = clock.now + 100
    runner.play_case(table, "case:offline", deadline=cap)
    assert clock.now < cap, "Runner began a round that finished after the wave cap"


