"""Initial RFQ clocks with production Negotiator and virtual bounded model time."""

import copy
from itertools import product

import pytest
from arena_kit import complete_offer
from arena_kit.client import ArenaError
from arena_kit.sim import load_cases

from buyer import llm, policy, runner


class VirtualClock:
    now = 1000.0

    def time(self):
        return self.now

    monotonic = time

    def advance(self, duration):
        self.now += duration


class TimedTable:
    session_id = "local-queue"

    def __init__(self, clock, bidders, reply_s):
        self.clock, self.reply_s = clock, reply_s
        self.case = copy.deepcopy(load_cases()["case:S01"])
        self.events = {
            f"sup:local-{index}": [{
                "from": "supplier", "status": "open", "body": "Our offer.",
                "term_sheets": [{
                    "term_sheet_id": f"offer:{index}",
                    "terms": complete_offer(self.case, {"unit_price": 16 + index}),
                }],
            }] for index in range(bidders)
        }
        self.last_reply = dict.fromkeys(self.events, clock.now)
        self.arrivals = []

    def open(self, case_id):
        return self.case, copy.deepcopy(self.events)

    def send(self, sid, message):
        age = self.clock.now - self.last_reply[sid]
        self.arrivals.append((sid, age))
        if age > runner.CLOCK_S:
            raise ArenaError(409, "late buyer message")
        self.clock.advance(self.reply_s)
        self.last_reply[sid] = self.clock.now
        return {**self.events[sid][0], "status": "final_offer"}

    def missed(self, sid, error):
        return {"from": "supplier", "status": "walked_away", "term_sheets": []}

    def close(self, sid, message):
        return {"deal": message["action"]["type"] == "accept"}


def rehearse(monkeypatch, bidders, reply_s, writer_s):
    clock = VirtualClock()
    monkeypatch.setattr(runner, "time", clock)
    monkeypatch.setattr(policy, "time", clock)
    monkeypatch.setattr(runner, "save", lambda *args: None)
    budgets = []

    def paragraph(complete, brief, timeout=llm.TIMEOUT_S):
        # Model wall-clock behavior is deterministic here; real worker timeout is
        # separately verified by test_guards and test_runtime_regressions.
        budgets.append(timeout)
        if timeout < llm.MIN_S:
            return None
        allowed = min(timeout, llm.TIMEOUT_S)
        clock.advance(min(writer_s, allowed))
        return "Thank you for considering our proposal." if writer_s <= allowed else None

    monkeypatch.setattr(llm, "paragraph", paragraph)
    table = TimedTable(clock, bidders, reply_s)
    runner.play_case(table, table.case["case_id"], complete=lambda *args: "unused")
    return table, budgets


@pytest.mark.parametrize("bidders,reply_s,writer_s", list(product([1, 2, 3], [5, 10, 20, 25], [0, 5, 15])))
def test_initial_queue_meets_each_supplier_deadline(monkeypatch, bidders, reply_s, writer_s):
    table, _ = rehearse(monkeypatch, bidders, reply_s, writer_s)
    assert len({sid for sid, _ in table.arrivals}) == bidders
    assert all(age <= runner.CLOCK_S - runner.MARGIN_S for _, age in table.arrivals), table.arrivals


def test_initial_three_bidder_slow_reply_skips_writer(monkeypatch):
    table, budgets = rehearse(monkeypatch, 3, 25, 15)
    assert [age for _, age in table.arrivals[:3]] == [0, 25, 50]
    assert budgets[0] < llm.MIN_S


def test_single_bidder_still_has_full_writer_budget(monkeypatch):
    table, budgets = rehearse(monkeypatch, 1, 25, 15)
    assert budgets[0] == llm.TIMEOUT_S
    assert table.arrivals[0][1] == 15


def test_unavoidable_serial_latency_is_identified(monkeypatch):
    # With three bidders and 35s per reply, even instant templates reach the
    # third only at 70s. This is outside the feasible envelope, not a promise
    # that a local budget can fix the arena's serial session transport.
    table, _ = rehearse(monkeypatch, 3, 35, 0)
    assert [age for _, age in table.arrivals[:3]] == [0, 35, 70]

