   manifest['open_sessions'].append({'set':set_,**row});continue
  path=out/'sessions'/set_/f'{case}_{sid}.json';path.parent.mkdir(parents=True,exist_ok=True)
  historical=old/set_/path.name
  if historical.exists():
   if not path.exists():path.write_bytes(historical.read_bytes())
   manifest['known_sessions'].append({'set':set_,**row})
  else:jobs.append((set_,row,path))
 print(json.dumps({'set':set_,'catalog_sessions':len(rows),'complete':sum(r['status']=='ended' for r in rows)}),flush=True)

