   try:state['backoffice']=client.backoffice(sid)
   except ArenaError:state['backoffice']=None
   state['fetched_threads']={sup:client.thread(sid,sup) for sup in state.get('threads',{})}
   path.write_text(json.dumps(state,indent=2,ensure_ascii=False))
  r=state.get('result')or{}
  return {'set':set_,**row,'score':r.get('score'),'deal':r.get('deal'),'path':str(path),'trace_events':len(r.get('trace',[]))}
 except Exception as e:return {'set':set_,**row,'error':str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
 for row in pool.map(fetch,jobs):
  manifest['errors' if 'error' in row else 'new_sessions'].append(row)
  print(json.dumps({k:row.get(k) for k in ('set','session_id','case_id','score','deal','error')}),flush=True)
  (out/'manifest.json').write_text(json.dumps(manifest,indent=2))
(out/'manifest.json').write_text(json.dumps(manifest,indent=2))
print(json.dumps({'new':len(manifest['new_sessions']),'known':len(manifest['known_sessions']),'open':len(manifest['open_sessions']),'errors':len(manifest['errors'])}),flush=True)

