"""Read completed practice/sandbox sessions only. Never opens a negotiation."""
import concurrent.futures
import datetime
import json
from pathlib import Path
from arena_kit import ArenaClient, ArenaError
from arena_kit.cli import load_env
ROOT=Path('/Users/joaofmzuffo/ehl-codacabana-final')
load_env(ROOT/'.env')
client=ArenaClient(rate=2)
old=Path('/private/tmp/codacabana-pr12-full-review/logs/sessions')
out=ROOT/'out/latest-log-audit'
out.mkdir(parents=True,exist_ok=True)
manifest={'fetched_at':datetime.datetime.now(datetime.timezone.utc).isoformat(),'new_sessions':[],'known_sessions':[],'open_sessions':[],'errors':[]}
jobs=[]
for set_ in ('practice','sandbox'):
 rows=client.sessions(set_)
 (out/f'{set_}-catalog.json').write_text(json.dumps(rows,indent=2))
 cases=client.cases(set_)
 (out/f'{set_}-cases.json').write_text(json.dumps(cases,indent=2))
 for row in rows:
  sid=row['session_id'];case=row['case_id'].split(':')[-1]
  if row['status']!='ended':
   manifest['open_sessions'].append({'set':set_,**row});continue
  path=out/'sessions'/set_/f'{case}_{sid}.json';path.parent.mkdir(parents=True,exist_ok=True)
  historical=old/set_/path.name
  if historical.exists():
   if not path.exists():path.write_bytes(historical.read_bytes())
   manifest['known_sessions'].append({'set':set_,**row})
  else:jobs.append((set_,row,path))
 print(json.dumps({'set':set_,'catalog_sessions':len(rows),'complete':sum(r['status']=='ended' for r in rows)}),flush=True)

def fetch(job):
 set_,row,path=job;sid=row['session_id']
 try:
  if path.exists():state=json.loads(path.read_text())
  else:
   state=client.session(sid)
   try:state['backoffice']=client.backoffice(sid)
   except ArenaError:state['backoffice']=None
   state['fetched_threads']={sup:client.thread(sid,sup) for sup in state.get('threads',{})}
   path.write_text(json.dumps(state,indent=2,ensure_ascii=False))
  r=state.get('result')or{}
  return {'set':set_,**row,'score':r.get('score'),'deal':r.get('deal'),'path':str(path),'trace_events':len(r.get('trace',[]))}
 except Exception as e:return {'set':set_,**row,'error':str(e)}
with concurrent.futures.ThreadPoolExecutor(max_workers=3) as pool:
 for row in pool.map(fetch,jobs):
  manifest['errors' if 'error' in row else 'new_sessions'].append(row)
  print(json.dumps({k:row.get(k) for k in ('set','session_id','case_id','score','deal','error')}),flush=True)
  (out/'manifest.json').write_text(json.dumps(manifest,indent=2))
(out/'manifest.json').write_text(json.dumps(manifest,indent=2))
print(json.dumps({'new':len(manifest['new_sessions']),'known':len(manifest['known_sessions']),'open':len(manifest['open_sessions']),'errors':len(manifest['errors'])}),flush=True)

