import json,collections,statistics,datetime
for name in ['practice','sandbox']:
 d=json.load(open(f'out/latest-log-audit/{name}-catalog.json'))
 by=collections.defaultdict(list)
 for x in d: by[x['case_id'].split(':')[-1]].append(x)
 print(name,'n',len(d),'ended',sum(x['status']=='ended' for x in d),'deals',sum(bool(x.get('deal')) for x in d),'mean',statistics.mean(x['score'] for x in d if x['score'] is not None))
 for case,items in sorted(by.items()):
  scores=[x['score'] for x in items if x['score'] is not None]
  last=sorted(items,key=lambda x:x['created_at'])[-1]
  print(case,len(items),sum(bool(x.get('deal')) for x in items),round(statistics.mean(scores),6),round(max(scores),6),round(last['score'],6),last['session_id'])
 if name=='practice':
  best=[max(x['score'] for x in items if x['score'] is not None) for items in by.values()]
  latest=[sorted(items,key=lambda x:x['created_at'])[-1]['score'] for items in by.values()]
  print('best mean',statistics.mean(best),'latest mean',statistics.mean(latest))
