const r=await Promise.allSettled([
  tools.exec_command({cmd:"python3 - <<'PY'
import json,pathlib,collections,statistics
root=pathlib.Path('out/latest-log-audit/sessions')
for env in ('practice','sandbox'):
 files=list((root/env).glob('*.json'))
 ids={}; end=collections.Counter();claims=collections.Counter();timeouts=0;timeout_sessions=set(); supplier=collections.Counter()
 for p in files:
  try:d=json.loads(p.read_text())
  except Exception:continue
  if d.get('status')!='ended' or not d.get('result'):continue
  ids[d['session_id']]=d
  end[d.get('end_reason') or 'unknown']+=1
  if d['result'].get('deal'):supplier[d['result'].get('supplier_id')]+=1
  for t in d['result'].get('trace',[]):
   m=t.get('move',{})
   for c in m.get('claim_results',[]): claims[c.get('result','unknown')]+=1
   if m.get('type')=='timeout':timeouts+=1;timeout_sessions.add(d['session_id'])
